"""Utlizamos el metodo de imputacion por la media de las variables Baños,Habitaciones,Camas, en base al tipo de habitacion

"""

cols_to_impute = ['Baños', 'Habitaciones', 'Camas']
columnas_agrupacion = ['Tipo de Habitación']

df_temp = df.copy()

for col in cols_to_impute:
    df[col] = pd.to_numeric(df[col], errors='coerce').astype(float)

    df_temp[col] = pd.to_numeric(df_temp[col], errors='coerce').astype(float)
    df_temp[col] = np.where(df_temp[col] == 0, np.nan, df_temp[col])
    df_temp[col] = df_temp[col].replace(np.nan, np.nan)

for col in cols_to_impute:
    mean_by_group = df_temp.groupby(columnas_agrupacion)[col].transform('mean')

    missing_or_zero = (df[col].isna()) | (df[col] == 0)

    # Asignación explícita para evitar FutureWarning
    df.loc[missing_or_zero, col] = mean_by_group.loc[missing_or_zero].astype(float)

df['Baños'] = (df['Baños'] * 2).round() / 2
df['Baños'] = df['Baños'].round(1)

for col in ['Habitaciones', 'Camas']:
    df[col] = pd.to_numeric(df[col], errors='coerce')
    mean_global_temp = df[col].mean()

    # Eliminamos inplace=True y asignamos el resultado
    df[col] = df[col].fillna(mean_global_temp)

    df[col] = df[col].round().astype('Int64')

for col in cols_to_impute:
    if df[col].isna().any():
        mean_global = df[col].mean()

        if col == 'Baños':
            mean_global = (mean_global * 2).round() / 2
            mean_global = mean_global.round(1)
        elif col in ['Habitaciones', 'Camas']:
            mean_global = int(round(mean_global))

        # Eliminamos inplace=True y asignamos el resultado
        df[col] = df[col].fillna(mean_global)

