summary_stats['skewness'] = skew_values

final_quantitative_summary = summary_stats[[
    'count', 'mean', 'mode', '50%', 'std', 'min', 'max', '25%', '75%', 'skewness'
]].rename(columns={'50%': 'median', '25%': 'Q1', '75%': 'Q3','skewness': 'Asimetria'})

qualitative_summaries = {}

for col in qualitative_cols:
    freq = df[col].value_counts()
    rel_freq = df[col].value_counts(normalize=True).mul(100).round(2)

    summary = pd.DataFrame({
        'Frecuencia Absoluta': freq,
        'Frecuencia Relativa (%)': rel_freq
    })

    moda = freq.index[0]

    qualitative_summaries[col] = (moda, summary)

print("Resumen Estadístico Cuantitativo:")
print(final_quantitative_summary.to_string())

print("\nResumen Estadístico Cualitativo:")

for col, (moda, summary) in qualitative_summaries.items():
    print(f"\n[VARIABLE: {col}]")
    print(f"Moda: {moda}")
    print("Tabla de Frecuencias:")
    print(summary.to_string())

