file_name = "25.11_Base_de_Datos_-_AirBnB.csv"
df = pd.read_csv(file_name, delimiter=';')
def clean_convert_ratings(df, columns):
    for col in columns:
        if col in df.columns:
            series = df[col].astype(str).str.replace(',', '.', regex=False)
            df[col] = pd.to_numeric(series, errors='coerce')
    return df

def imputar_por_media(df, columna):
    if columna not in df.columns:
        print(f"Advertencia: Columna '{columna}' no encontrada para imputar media.")
        return df

    if pd.api.types.is_numeric_dtype(df[columna]):
        media = df[columna].mean(skipna=True)
        df[columna] = df[columna].fillna(media)
    else:
        print(f"Advertencia: Columna '{columna}' no es numérica, no se imputó media.")

    return df

rating_columns = [
    'Rating General',
    'Rating Precisión',
    'Rating Limpieza',
    'Rating Check In',
    'Rating Comunicación',
    'Rating Localización'
]

df = clean_convert_ratings(df, rating_columns)

for col in rating_columns:
    df = imputar_por_media(df, col)

print("--- DataFrame Limpiado e Imputado (Solo Ratings) ---")
