for current_idx, variable in enumerate(num_cols):
    i = current_idx // columns
    j = current_idx % columns
    # Flatten the axes array if there's only one row to avoid indexing issues
    if rows == 1:
        sns.histplot(df[variable], ax=axes[j], kde=True)
        axes[j].set_title(variable)
        axes[j].set_xlabel("")
    else:
        sns.histplot(df[variable], ax=axes[i][j], kde=True)
        axes[i][j].set_title(variable)
        axes[i][j].set_xlabel("")

# Remove any unused subplots
